?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>API024 테스트</title><style>body{font-family:system-ui,sans-serif;max-width:1100px;margin:35px auto;padding:0 16px;color:#18202a}input,button{padding:11px;font-size:15px}input{width:65%}button{background:#20252b;color:#fff;border:0;border-radius:6px}table{border-collapse:collapse;width:100%;margin-top:20px}th,td{border:1px solid #ddd;padding:8px;text-align:left;font-size:13px}.err{background:#fee;padding:12px}.ok{background:#eef8ef;padding:12px}.muted{color:#667085}</style></head><body><h1>관세청 API024 입출항보고내역 테스트</h1><p class="muted">v1.7-final · API024 전용키 · 호출부호(shipCallImoNo) → 입항내역 교차검증</p><form><input name="call_sign" value="<?=h($call)?>" placeholder="예: 3FEN2"><button>입항조회</button></form><p><a href="carriers.php">← 자동차운반선 후보</a></p><?php if($err):?><div class="err"><?=h($err)?></div><?php endif;?><?php if($res):?><div class="ok">HTTP <?=h($res['http'])?> / tCnt <?=h($res['count'])?> / 실제 파싱 <?=count($res['rows'])?>건 <?=h($res['notice'])?></div><table><tr><th>입항일</th><th>선박명</th><th>출발항</th><th>세관</th><th>계선장소</th><th>입출항제출번호</th><th>판정</th></tr><?php foreach($res['rows'] as $r):?><tr><td><?=h(tp_iopr_digits_dt($r['arrival_at'])?:$r['arrival_at'])?></td><td><?=h($r['ship_name'])?></td><td><?=h($r['departure_port_name'])?></td><td><?=h($r['customs_name'])?></td><td><?=h($r['berth_name'])?></td><td><?=h($r['submission_no'])?></td><td><?=tp_iopr_is_china_port((string)$r['departure_port_name'],(string)$r['departure_port_code'])?'중국발':'-'?></td></tr><?php endforeach;?></table><?php endif;?></body></html>
